class Order {
    String customer; double total;
    Order(String customer, double total) { this.customer = customer; this.total = total; }
    String getCustomer() { return customer; } double getTotal() { return total; }
}

List<Order> orders = List.of(
    new Order("Kowalski", 150), new Order("Nowak", 300), new Order("Kowalski", 200),
    new Order("Wisniewski", 90), new Order("Nowak", 120), new Order("Kowalski", 80),
    new Order("Wisniewski", 400), new Order("Nowak", 60)
);
Map<String, Double> sumsByCustomer = orders.stream()
        .collect(Collectors.groupingBy(Order::getCustomer, Collectors.summingDouble(Order::getTotal)));

List<Map.Entry<String, Double>> ranking = new ArrayList<>(sumsByCustomer.entrySet());
ranking.sort(Map.Entry.<String, Double>comparingByValue().reversed());
ranking.forEach(e -> System.out.println(e.getKey() + ": " + e.getValue()));

