List<Integer> numbers = List.of(4, 8, 15, 16, 23, 42);
AtomicInteger indexHolder = new AtomicInteger(1);

Collector<Integer, StringBuilder, String> indexedJoiner = Collector.of(
    StringBuilder::new,
    (sb, value) -> {
        if (sb.length() > 0) sb.append(", ");
        sb.append(indexHolder.getAndIncrement()).append(":").append(value);
    },
    (sb1, sb2) -> sb1.append(sb2), // combiner (dla przetwarzania rownoleglego)
    StringBuilder::toString
);

String result = numbers.stream().collect(indexedJoiner);
System.out.println(result);

class Item {
