    System.out.println(cat + ": min=" + stats.getMin() + ", max=" + stats.getMax() + ", avg=" + stats.getAverage()));

class Transaction {
    String date, category; double amount;
    Transaction(String date, String category, double amount) { this.date = date; this.category = category; this.amount = amount; }
    String getCategory() { return category; } double getAmount() { return amount; }
}

List<Transaction> transactions = List.of(
    new Transaction("01-01", "Jedzenie", 50), new Transaction("01-02", "Jedzenie", 150),
    new Transaction("01-03", "Transport", 30), new Transaction("01-04", "Jedzenie", 200),
    new Transaction("01-05", "Rozrywka", 120), new Transaction("01-06", "Transport", 80),
    new Transaction("01-07", "Rozrywka", 40), new Transaction("01-08", "Jedzenie", 25),
    new Transaction("01-09", "Transport", 300), new Transaction("01-10", "Rozrywka", 90)
);
Map<String, Map<Boolean, List<Transaction>>> report = transactions.stream()
        .collect(Collectors.groupingBy(Transaction::getCategory,
                Collectors.partitioningBy(t -> t.getAmount() > 100)));

report.forEach((category, split) -> {
    System.out.println(category + ":");
    System.out.println("  powyzej 100: " + split.get(true).size());
    System.out.println("  ponizej/rowne 100: " + split.get(false).size());
});
